const puppeteer = require('/home/dp/.npm-global/lib/node_modules/puppeteer-core');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({
    executablePath: '/usr/bin/google-chrome',
    headless: 'new',
    args: ['--no-sandbox', '--disable-dev-shm-usage', '--force-device-scale-factor=1']
  });
  const page = await browser.newPage();
  const errors = [];
  const requests = [];
  page.on('console', msg => { if (msg.type() === 'error') errors.push('console: ' + msg.text()); });
  page.on('pageerror', err => errors.push('pageerror: ' + err.message));
  page.on('request', req => requests.push(req.url()));
  await page.setViewport({width: 1440, height: 1000, deviceScaleFactor: 1});
  const url = 'file://' + path.resolve('index.html');
  await page.goto(url, {waitUntil: 'networkidle0'});
  await new Promise(r => setTimeout(r, 300));

  const state = async () => page.evaluate(() => ({
    intro: !document.querySelector('#view-intro').hidden,
    test: !document.querySelector('#view-test').hidden,
    result: !document.querySelector('#view-result').hidden,
    stepLabel: document.querySelector('#stepLabel').textContent,
    activePane: document.querySelector('.pane:not([hidden])')?.dataset.stepPane,
    activeTab: document.querySelector('.tab.is-active')?.textContent,
    nextHidden: document.querySelector('#nextBtn').hidden,
    finishHidden: document.querySelector('#finishBtn').hidden,
    prevDisabled: document.querySelector('#prevBtn').disabled,
    progress: document.querySelector('#discProgress').style.width,
    score: document.querySelector('#scoreLine').textContent,
    visiblePanes: [...document.querySelectorAll('.pane')].filter(p=>!p.hidden).length,
  }));

  console.log('initial', await state());
  await page.screenshot({path: '/tmp/shot-intro-1440.png', fullPage: true});

  await page.click('#startBtn');
  await new Promise(r => setTimeout(r, 300));
  console.log('after start', await state());
  console.log('focused', await page.evaluate(() => document.activeElement?.id || document.activeElement?.className));
  await page.screenshot({path: '/tmp/shot-step1-1440.png', fullPage: true});

  // baseline: next through all steps
  for (let i=0;i<7;i++) { await page.click('#nextBtn'); await new Promise(r=>setTimeout(r,60)); }
  console.log('last step', await state());
  await page.screenshot({path: '/tmp/shot-step8-1440.png', fullPage: true});
  await page.click('#finishBtn');
  await new Promise(r => setTimeout(r, 300));
  console.log('result baseline', await state());
  await page.screenshot({path: '/tmp/shot-result-1440.png', fullPage: true});

  // restart, test keyboard reorder on first list
  await page.click('#restartBtn');
  await new Promise(r=>setTimeout(r,200));
  console.log('after restart', await state());
  const before = await page.$$eval('#draggable-list1 .rank-item__text', els => els.map(e=>e.textContent));
  await page.focus('#draggable-list1 .disc-item');
  await page.keyboard.press('ArrowDown');
  await new Promise(r=>setTimeout(r,100));
  const after = await page.$$eval('#draggable-list1 .rank-item__text', els => els.map(e=>e.textContent));
  console.log('keyboard reorder', before, '->', after);
  console.log('aria labels', await page.$$eval('#draggable-list1 .disc-item', els => els.map(e=>e.getAttribute('aria-label'))));

  // restart again, test pointer drag on list 2: drag first item below third
  await page.click('#prevBtn'); // back? currently step 0, prev disabled -> no-op
  const box = await page.evaluate(() => {
    const items = [...document.querySelectorAll('#draggable-list2 .disc-item')];
    const a = items[0].getBoundingClientRect();
    const c = items[2].getBoundingClientRect();
    return {x: a.left + a.width/2, y: a.top + a.height/2, ty: c.top + c.height/2 + 8};
  });
  await page.mouse.move(box.x, box.y);
  await page.mouse.down();
  await page.mouse.move(box.x, box.y + 20, {steps: 4});
  await page.mouse.move(box.x, box.ty, {steps: 8});
  await page.mouse.up();
  await new Promise(r=>setTimeout(r,150));
  console.log('drag list2', await page.$$eval('#draggable-list2 .rank-item__text', els => els.map(e=>e.textContent)));

  // check score after deliberate ordering: set list1 order d,i,s,c major=d minor=c
  const scoreAfter = await page.evaluate(() => {
    // go finish by clicking tabs then finish
    document.querySelector('[data-step-btn="7"]').click();
    document.querySelector('#finishBtn').click();
    return document.querySelector('#scoreLine').textContent;
  });
  console.log('score after changes', scoreAfter);

  // external requests
  console.log('requests', [...new Set(requests)]);
  console.log('errors', errors);

  // responsive screenshots
  for (const [w,h,name] of [[1024,900,'1024'],[768,1000,'768'],[390,844,'390']]) {
    await page.setViewport({width:w,height:h,deviceScaleFactor:1});
    await page.evaluate(() => { location.reload(); });
    await page.waitForFunction(() => document.readyState === 'complete');
    await new Promise(r=>setTimeout(r,250));
    await page.screenshot({path: `/tmp/shot-intro-${name}.png`, fullPage: true});
